import{_ as a,o as t,c as i,ae as s}from"./chunks/framework.B2ul6ABY.js";const p=JSON.parse('{"title":"Saivage v3 Runbook","description":"","frontmatter":{},"headers":[],"relativePath":"runbook/index.md","filePath":"runbook/index.md"}'),o={name:"runbook/index.md"};function n(r,e,l,c,d,h){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="saivage-v3-runbook" tabindex="-1">Saivage v3 Runbook <a class="header-anchor" href="#saivage-v3-runbook" aria-label="Permalink to &quot;Saivage v3 Runbook&quot;">​</a></h1><p>This runbook is the current operator entry point for starting, controlling, diagnosing, and releasing Saivage v3. It consolidates the prior operation guide, operator runbook, troubleshooting guide, and release checklist while leaving source-of-truth architecture in <a href="/docs/agents.html">Agents and Runtime Architecture</a>.</p><h2 id="sections" tabindex="-1">Sections <a class="header-anchor" href="#sections" aria-label="Permalink to &quot;Sections&quot;">​</a></h2><ul><li><a href="./operations.html">Operations</a> — startup, auth, public/protected surfaces, health, runtime state, pause/resume/freeze, WebSocket chat, backups, and LXC/systemd operations.</li><li><a href="./incidents.html">Incidents</a> — unauthorized access, stale UI state, frozen/error runtime recovery, evidence issues, preview-only actions, and degraded-agent workflows.</li><li><a href="./release.html">Release</a> — release-candidate documentation, security, runtime-control, build, web, and serving gates.</li><li><a href="./lxc-operations.html">LXC operations</a> — deployment-oriented LXC notes, systemd unit names, journal checks, and safe restart flow.</li></ul><h2 id="quick-operator-sequence" tabindex="-1">Quick operator sequence <a class="header-anchor" href="#quick-operator-sequence" aria-label="Permalink to &quot;Quick operator sequence&quot;">​</a></h2><ol><li>Confirm the service is reachable:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/health</span></span></code></pre></div><ol start="2"><li>Confirm authenticated runtime state:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SAIVAGE_API_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  http://localhost:8080/api/state</span></span></code></pre></div><ol start="3"><li>Pause before low-risk maintenance, or freeze before disruptive handoff.</li><li>Inspect Debug, Cards, Agents, Files, and Notifications in the Web Control Room before editing runtime files manually.</li><li>Use this runbook for procedures and <a href="./incidents.html">Troubleshooting incidents</a> for recovery paths.</li></ol><h2 id="verification-contract" tabindex="-1">Verification contract <a class="header-anchor" href="#verification-contract" aria-label="Permalink to &quot;Verification contract&quot;">​</a></h2><p><code>npm run docs:verify</code> runs <code>scripts/check-runbook-curl-examples.js</code>. That guard extracts the curl/http examples in <code>docs/runbook/*.md</code>, checks that every documented route exists in the source route table, and validates the documented top-level response keys/status codes for <code>/health</code>, <code>/api/state</code>, <code>/api/runtime/pause</code>, and <code>/api/runtime/resume</code> against a freshly seeded temporary runtime fixture.</p>`,12)])])}const k=a(o,[["render",n]]);export{p as __pageData,k as default};
